"""Date ranges."""
from datetime import timedelta


def _validate_step(step):
    if isinstance(step, bool) or not isinstance(step, int) or step < 1:
        raise ValueError("step must be a positive integer")


def dates_between(start, end, step=1):
    """List dates from start toward end, including end when reached."""
    _validate_step(step)
    days = (end - start).days
    direction = 1 if days >= 0 else -1
    return [
        start + timedelta(days=direction * offset)
        for offset in range(0, abs(days) + 1, step)
    ]


def count_dates(start, end, step=1):
    """Count dates in the range without constructing it."""
    _validate_step(step)
    return abs((end - start).days) // step + 1
